(7080385, 1077617, 59737, '<td valign="top">Nice scene, great fog and sky.  Great placement of the tree in the frame, really nice tones throughout.</td>', 'Nice scene, great fog and sky.  Great placement of the tree in the frame, really nice tones throughout.', '2013-08-01 22:33:55.000000', NULL, 1),
