(7080586, 1077702, 108580, '<td valign="top">Poor as dirt yet happier than 99% of spoilt western brats. Lovely thought provoking and humbling image. RAW honest Africa. Maybe a few "technical flaws" like skew horizon and tight on the right hand but this is shot from the hip and street, thus you''re forgiven :)</td>', 'Poor as dirt yet happier than 99% of spoilt western brats. Lovely thought provoking and humbling image. RAW honest Africa. Maybe a few "technical flaws" like skew horizon and tight on the right hand but this is shot from the hip and street, thus you''re forgiven :)', '2013-08-02 03:22:33.000000', NULL, 1),
(7080656, 1077173, 88947, '<td valign="top">Nice!</td>', 'Nice!', '2013-08-02 07:02:24.000000', NULL, 1),
