(7080828, 1077526, 59737, '<td valign="top">If you were going for that dreamy hazy memory feeling you definitely got it, the processing and blue work well with the title to give that feeling.</td>', 'If you were going for that dreamy hazy memory feeling you definitely got it, the processing and blue work well with the title to give that feeling.', '2013-08-02 12:57:18.000000', NULL, 1),
(7080833, 1077180, 59737, '<td valign="top">Good night shot, the title doesn''t work with the image for me.  The title makes me want to see some details of people doing something on a warm night in SF.  Good job with the exposure and like that there''s still color in the sky.</td>', 'Good night shot, the title doesn''t work with the image for me.  The title makes me want to see some details of people doing something on a warm night in SF.  Good job with the exposure and like that there''s still color in the sky.', '2013-08-02 13:00:50.000000', NULL, 1),
