(7082268, 1077382, 114285, '<td valign="top">Ahhh here is my Verineat <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1070026" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg"/></a> <br/> <br/>I feel the silence, I feel the warmth, just lovely, what a wonderful melancholy comp, with the birds added, very good art! 10</td>', 'Ahhh here is my Verineat   I feel the silence, I feel the warmth, just lovely, what a wonderful melancholy comp, with the birds added, very good art! 10', '2013-08-06 01:59:31.000000', NULL, 1),
(7082269, 1077173, 114285, '<td valign="top">Sensational candid photo.<br/> <br/>Wonderful processing.<br/> <br/>Wondering if it will get the love it deserves, most likely not on here, it''s way too artistic for most on here, in my top three.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1070026" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/110000-114999/114285/120/Copyrighted_Image_Reuse_Prohibited_1070026.jpg"/></a> Bumping to a 10.</td>', 'Sensational candid photo. Wonderful processing. Wondering if it will get the love it deserves, most likely not on here, it''s way too artistic for most on here, in my top three.  Bumping to a 10.', '2013-08-06 02:00:23.000000', NULL, 1),
(7082270, 1077617, 114285, '<td valign="top">lovely stillness to this, top ten for me!</td>', 'lovely stillness to this, top ten for me!', '2013-08-06 02:01:09.000000', NULL, 1),
(7082271, 1077040, 114285, '<td valign="top">wonderful, 8</td>', 'wonderful, 8', '2013-08-06 02:01:26.000000', NULL, 1),
(7082272, 1077636, 114285, '<td valign="top">There is no rain, but maybe it''s hot - therefore the umbrella, or maybe you just added it for the fun, still lovely warmth to this, and love the water, and reflection.</td>', 'There is no rain, but maybe it''s hot - therefore the umbrella, or maybe you just added it for the fun, still lovely warmth to this, and love the water, and reflection.', '2013-08-06 02:03:25.000000', NULL, 1),
(7082273, 1077433, 114285, '<td valign="top">Great shot and warmth, 9</td>', 'Great shot and warmth, 9', '2013-08-06 02:03:49.000000', NULL, 1),
(7082318, 1077577, 108580, '<td valign="top">Beautiful study.</td>', 'Beautiful study.', '2013-08-06 04:00:21.000000', NULL, 1),
(7082333, 1074760, 108580, '<td valign="top">Wonderful candid. So spontaneous.</td>', 'Wonderful candid. So spontaneous.', '2013-08-06 05:01:05.000000', NULL, 1),
(7082335, 1077555, 108580, '<td valign="top">Nice slacks. Also very practical :)</td>', 'Nice slacks. Also very practical :)', '2013-08-06 05:03:08.000000', NULL, 1),
(7082336, 1077318, 108580, '<td valign="top">Another John street piece? Woks well with the juxtaposition quite literally between old and young.</td>', 'Another John street piece? Woks well with the juxtaposition quite literally between old and young.', '2013-08-06 05:04:24.000000', NULL, 1),
(7082394, 1077400, 108580, '<td valign="top">Great moment caught, not easy to do with wild game. Pity there''s a piece of plastic or paper in the bushes to right of foreground deer (behind it''s left ear) that really spoils it for me.</td>', 'Great moment caught, not easy to do with wild game. Pity there''s a piece of plastic or paper in the bushes to right of foreground deer (behind it''s left ear) that really spoils it for me.', '2013-08-06 08:54:41.000000', NULL, 1),
(7082399, 1077710, 108580, '<td valign="top">Cute shot, love the drops on the forehead and great focus on eyes, DOF. Not overly saturated either. Just a bit unbalanced composition. Crop off an inch or two on the right and perfect!</td>', 'Cute shot, love the drops on the forehead and great focus on eyes, DOF. Not overly saturated either. Just a bit unbalanced composition. Crop off an inch or two on the right and perfect!', '2013-08-06 08:57:53.000000', NULL, 1),
(7082401, 1077508, 108580, '<td valign="top">Lovely minimalist scape. My favourite kind. Kudo''s. Well perceived and photographed.</td>', 'Lovely minimalist scape. My favourite kind. Kudo''s. Well perceived and photographed.', '2013-08-06 08:58:38.000000', NULL, 1),
(7082403, 1077398, 108580, '<td valign="top">X-III=VII</td>', 'X-III=VII', '2013-08-06 09:00:38.000000', NULL, 1),
(7082407, 1077712, 108580, '<td valign="top">Lovely, light, dizzying. 8</td>', 'Lovely, light, dizzying. 8', '2013-08-06 09:04:11.000000', NULL, 1),
(7082409, 1077306, 108580, '<td valign="top">VII</td>', 'VII', '2013-08-06 09:04:27.000000', NULL, 1),
