(7082680, 1077371, 108580, '<td valign="top">Awesome light. Fabulous exposure. All enhancing figure, form and drama.</td>', 'Awesome light. Fabulous exposure. All enhancing figure, form and drama.', '2013-08-06 17:14:51.000000', NULL, 1),
(7082683, 1077678, 108580, '<td valign="top">Great flight shot of these little F1''s on wings :) Perfect still head and blurred wings. Great BG. Super catchlight. It however concerns me that as there is no environment (flower(s), stems, branches) that it may be a baited site. From a photographic skill and technicals POV it''s worth at least an 8. With the clean BG 9. Unbaited, with an actual flower, 10.</td>', 'Great flight shot of these little F1''s on wings :) Perfect still head and blurred wings. Great BG. Super catchlight. It however concerns me that as there is no environment (flower(s), stems, branches) that it may be a baited site. From a photographic skill and technicals POV it''s worth at least an 8. With the clean BG 9. Unbaited, with an actual flower, 10.', '2013-08-06 17:16:14.000000', NULL, 1),
(7082687, 1077000, 108580, '<td valign="top">I try to shoot and have been a big fan of candid for 30 years. This is right up my alley. Superb moment caught for all time. VWD. I''d also be in awe :)</td>', 'I try to shoot and have been a big fan of candid for 30 years. This is right up my alley. Superb moment caught for all time. VWD. I''d also be in awe :)', '2013-08-06 17:16:34.000000', NULL, 1),
